import { getBaseColumns } from './baseColumns';
import getBusinessColumns from './businessColumns';

import type { FormInstance } from 'antd';

const Embed = () => {
  const formRef = useRef<FormInstance>();
  const innerRef = useRef<SchemaFormInnerRefType>();

  const onFinish = async (values: any) => {
    console.log({ values, data: innerRef.current?.data });
    return true;
  };

  const [readonly, setReadonly] = useState(false);

  const [loading, setLoading] = useState(false);
  const handleFillData = () => {
    setLoading(true);
    setTimeout(() => {
      formRef.current?.setFieldsValue({
        base: {
          username: '\u738B\u5148\u751F',
          phone: '15588888',
          nickName: 'wang',
          sex: '\u7537',
          idNumber: 3202335566,
        },
        business: {
          company: '\u4FE1\u606F\u6280\u672F\u6709\u9650\u516C\u53F8',
          address: '\u6C5F\u82CF\u7701\u65E0\u9521\u5E02',
          serviceName: '1',
        },
      });
      setLoading(false);
    }, 500);
  };

  return (
    <div>
      <ProForm
        layout="horizontal"
        onFinish={onFinish}
        submitter={false}
        formRef={formRef}
        innerRef={innerRef}
        readonly={readonly} // \u4E5F\u53EF\u4EE5\u5355\u72EC\u8BBE\u5728\u67D0\u4E2ASchemaForm\u4E0A
        initialValues={{ base: { username: '\u9AD8\u5148\u751F' } }}
      >
        <Card
          style={{ marginBottom: '24px' }}
          size="small"
          styles={{
            header: {
              background: '#ebebeb',
            },
          }}
          title="\u57FA\u672C\u4FE1\u606F"
        >
          <SchemaForm
            embed
            grid={true}
            rowProps={{ gutter: [0, 0] }}
            colProps={{ span: 8 }}
            labelCol={{ span: 9 }}
            columns={getBaseColumns()}
            valueBaseName="base"
          />
        </Card>

        <Card
          size="small"
          title="\u4E1A\u52A1\u4FE1\u606F"
          styles={{
            header: { background: '#ebebeb' },
          }}
        >
          <SchemaForm
            embed
            columns={getBusinessColumns()}
            labelCol={{ span: 3 }}
            valueBaseName="business"
          />
        </Card>
      </ProForm>

      <div style={{ marginTop: '10px', textAlign: 'end' }}>
        <Button
          style={{ marginRight: '10px' }}
          onClick={() => setReadonly((val) => !val)}
        >
          \u5207\u6362\u53EA\u8BFB
        </Button>
        <Button
          loading={loading}
          style={{ marginRight: '20px' }}
          onClick={handleFillData}
        >
          \u56DE\u663E\u6570\u636E
        </Button>
        <Button
          style={{ marginRight: '10px' }}
          onClick={() => formRef.current?.resetFields()}
        >
          \u91CD\u7F6E
        </Button>
        <Button type="primary" onClick={() => formRef.current?.submit()}>
          \u63D0\u4EA4
        </Button>
      </div>
    </div>
  );
};

export default Embed;
